-- Agent Hub initial durable execution storage.
-- RLS workspace-member blocks are generated by module-registry from the manifest.
-- Service will enforce stricter roles for write routes.

CREATE TABLE "agent_hub_executions" (
  "id" TEXT NOT NULL,
  "workspaceId" TEXT NOT NULL,
  "targetKind" TEXT NOT NULL,
  "targetId" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "revision" INTEGER NOT NULL DEFAULT 0,
  "attempt" INTEGER NOT NULL DEFAULT 0,
  "workerId" TEXT,
  "runtimeId" TEXT,
  "leaseUntil" TIMESTAMP(3),
  "checkpointRef" TEXT,
  "evidenceRefs" JSONB NOT NULL DEFAULT '[]',
  "verifiedBy" TEXT,
  "blockedReason" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "agent_hub_executions_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "agent_hub_events" (
  "id" TEXT NOT NULL,
  "workspaceId" TEXT NOT NULL,
  "executionId" TEXT NOT NULL,
  "revision" INTEGER NOT NULL,
  "action" TEXT NOT NULL,
  "actorId" TEXT NOT NULL,
  "data" JSONB NOT NULL DEFAULT '{}',
  "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "agent_hub_events_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "agent_hub_executions_workspaceId_updatedAt_idx" ON "agent_hub_executions"("workspaceId", "updatedAt");
CREATE INDEX "agent_hub_executions_workspaceId_targetKind_targetId_idx" ON "agent_hub_executions"("workspaceId", "targetKind", "targetId");
CREATE UNIQUE INDEX "agent_hub_events_executionId_revision_key" ON "agent_hub_events"("executionId", "revision");
CREATE INDEX "agent_hub_events_workspaceId_executionId_idx" ON "agent_hub_events"("workspaceId", "executionId");

-- A task may have many historical runs, but at most one active run.
CREATE UNIQUE INDEX "agent_hub_one_active_execution_per_target"
  ON "agent_hub_executions"("workspaceId", "targetKind", "targetId")
  WHERE "status" NOT IN ('done', 'failed', 'canceled');

ALTER TABLE "agent_hub_executions" ADD CONSTRAINT "agent_hub_executions_workspaceId_fkey"
  FOREIGN KEY ("workspaceId") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "agent_hub_events" ADD CONSTRAINT "agent_hub_events_workspaceId_fkey"
  FOREIGN KEY ("workspaceId") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "agent_hub_events" ADD CONSTRAINT "agent_hub_events_executionId_fkey"
  FOREIGN KEY ("executionId") REFERENCES "agent_hub_executions"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Row Level Security
ALTER TABLE "agent_hub_executions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "agent_hub_executions" FORCE ROW LEVEL SECURITY;
CREATE POLICY agent_hub_executions_isolation ON "agent_hub_executions"
  USING (EXISTS (
    SELECT 1 FROM "workspace_members" wm
    WHERE wm."workspaceId" = "agent_hub_executions"."workspaceId"
      AND wm."userId" = current_setting('app.current_user_id', true)
  ));

ALTER TABLE "agent_hub_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "agent_hub_events" FORCE ROW LEVEL SECURITY;
CREATE POLICY agent_hub_events_isolation ON "agent_hub_events"
  USING (EXISTS (
    SELECT 1 FROM "workspace_members" wm
    WHERE wm."workspaceId" = "agent_hub_events"."workspaceId"
      AND wm."userId" = current_setting('app.current_user_id', true)
  ));
